CREATE OR REPLACE FUNCTION public.paper_report_date_answers(_answers jsonb, _template uuid, _at timestamptz) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE a jsonb:=coalesce(_answers,'{}'::jsonb); f jsonb; d text:=to_char(_at AT TIME ZONE 'Europe/London','DD/MM/YYYY'); BEGIN a:=a||jsonb_build_object('date',d,'_paper_completion_at',_at); IF a ? 'inspection_date' THEN a:=a||jsonb_build_object('inspection_date',d); END IF; FOR f IN SELECT value FROM public.job_sheet_templates t, jsonb_array_elements(t.fields) WHERE t.id=_template LOOP IF lower(trim(f->>'label')) IN ('date','inspection date','service date','visit date','work date','test date','date of test','completion date','commissioning date','installation date') THEN a:=jsonb_set(a,ARRAY[f->>'id'],to_jsonb(d)); END IF; END LOOP; IF a ? '_scan_header' THEN a:=jsonb_set(a,'{_scan_header,date}',to_jsonb(d)); END IF; RETURN a; END $$;
REVOKE ALL ON FUNCTION public.paper_report_date_answers(jsonb,uuid,timestamptz) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.paper_report_date_answers(jsonb,uuid,timestamptz) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.align_paper_report_date() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j record; at_date timestamptz; BEGIN SELECT completed_at,historic_backfill,source INTO j FROM public.jobs WHERE id=NEW.job_id AND org_id=NEW.org_id; IF coalesce(j.historic_backfill,false) OR j.source LIKE 'paper backfill%' OR NEW.responses ? '_paper_completion_at' OR NEW.responses ? '_scan_source' THEN at_date:=coalesce((NEW.responses->>'_paper_completion_at')::timestamptz,j.completed_at,NEW.submitted_at,now()); NEW.responses:=public.paper_report_date_answers(NEW.responses,NEW.template_id,at_date); IF NEW.status='submitted' THEN NEW.submitted_at:=at_date; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER align_paper_report_date BEFORE INSERT OR UPDATE OF responses,submitted_at ON public.job_sheet_responses FOR EACH ROW EXECUTE FUNCTION public.align_paper_report_date();
CREATE OR REPLACE FUNCTION public.sync_paper_job_date() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (NEW.historic_backfill OR NEW.source LIKE 'paper backfill%') AND NEW.completed_at IS DISTINCT FROM OLD.completed_at AND NEW.completed_at IS NOT NULL THEN UPDATE public.job_sheet_responses r SET responses=public.paper_report_date_answers(r.responses,r.template_id,NEW.completed_at), submitted_at=CASE WHEN r.status='submitted' THEN NEW.completed_at ELSE r.submitted_at END WHERE r.job_id=NEW.id AND r.org_id=NEW.org_id; UPDATE public.asset_service_history SET inspection_date=NEW.completed_at,report_date_text=to_char(NEW.completed_at AT TIME ZONE 'Europe/London','DD/MM/YYYY') WHERE job_id=NEW.id AND org_id=NEW.org_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER sync_paper_job_date AFTER UPDATE OF completed_at ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.sync_paper_job_date();
CREATE OR REPLACE FUNCTION public.set_paper_report_completion_date(_response_id uuid, _date date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; j record; at_date timestamptz:=coalesce(_date,current_date)::timestamp AT TIME ZONE 'UTC'; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to change the report date'; END IF; SELECT * INTO r FROM public.job_sheet_responses WHERE id=_response_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Report not found'; END IF; IF NOT (public.has_role_in_org(auth.uid(),r.org_id,'admin') OR public.is_org_admin(r.org_id) OR public.is_platform_admin(auth.uid())) THEN RAISE EXCEPTION 'Only your company office can change this date'; END IF; SELECT * INTO j FROM public.jobs WHERE id=r.job_id AND org_id=r.org_id FOR UPDATE; IF NOT FOUND OR NOT (coalesce(j.historic_backfill,false) OR j.source LIKE 'paper backfill%' OR r.responses ? '_scan_source' OR r.responses ? '_paper_completion_at') THEN RAISE EXCEPTION 'This is not a paper-scan report'; END IF; at_date:=at_date+interval '12 hours'; UPDATE public.jobs SET completed_at=at_date WHERE id=j.id AND org_id=r.org_id; UPDATE public.job_sheet_responses SET responses=public.paper_report_date_answers(responses,template_id,at_date),submitted_at=CASE WHEN status='submitted' THEN at_date ELSE submitted_at END WHERE id=r.id AND org_id=r.org_id; UPDATE public.asset_service_history SET inspection_date=at_date,report_date_text=to_char(at_date,'DD/MM/YYYY') WHERE job_sheet_response_id=r.id AND org_id=r.org_id; INSERT INTO public.job_activity_log(job_id,user_id,action,details) VALUES(j.id,auth.uid(),'report_date_changed','Paper report completion date changed to '||to_char(_date,'DD/MM/YYYY')); END $$;
REVOKE ALL ON FUNCTION public.set_paper_report_completion_date(uuid,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_paper_report_completion_date(uuid,date) TO authenticated;
REVOKE ALL ON FUNCTION public.align_paper_report_date() FROM PUBLIC,anon; REVOKE ALL ON FUNCTION public.sync_paper_job_date() FROM PUBLIC,anon;